import{_ as o,a0 as n,w as d,s as r,I as a,x as i,a1 as t,A as l,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"每個 Linux 新手都應該知道的 10 個命令 | LCTT x X-CMD","titleTemplate":false,"description":"每個 Linux 新手都應該知道的 10 個命令 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每個 Linux 新手都應該知道的 10 個命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每個 Linux 新手都應該知道的 10 個命令 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180403 10 fundamental commands for new Linux users","title":"每個 Linux 新手都應該知道的 10 個命令","tag":"201805","desc":""},"relativePath":"201805/20180403 10 fundamental commands for new Linux users.md","filePath":"[post].md"}'),c={name:"201805/20180403 10 fundamental commands for new Linux users.md"};function h(u,e,m,g,k,b){const s=n("Link");return d(),r("div",null,[e[18]||(e[18]=a("h1",{id:"每個-linux-新手都應該知道的-10-個命令",tabindex:"-1"},[i("每個 Linux 新手都應該知道的 10 個命令 "),a("a",{class:"header-anchor",href:"#每個-linux-新手都應該知道的-10-個命令","aria-label":"Permalink to “每個 Linux 新手都應該知道的 10 個命令”"},"​")],-1)),e[19]||(e[19]=a("blockquote",null,[a("p",null,"通過這 10 個基礎命令開始掌握 Linux 命令列。")],-1)),e[20]||(e[20]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/osdc_terminals.png?itok=CfBqYBah",alt:""})],-1)),a("p",null,[e[2]||(e[2]=i("你可能認為你是 Linux 新手，但實際上並不是。全球互聯網用户有 ",-1)),t(s,{href:"https://hostingcanada.org/state-of-the-internet/"},{default:l(()=>[...e[0]||(e[0]=[i("3.74 億",-1)])]),_:1}),e[3]||(e[3]=i("，他們都以某種方式使用 Linux，因為 Linux 服務器佔據了互聯網的 90%。大多數現代路由器運行 Linux 或 Unix，",-1)),t(s,{href:"https://www.top500.org/statistics/details/osfam/1"},{default:l(()=>[...e[1]||(e[1]=[i("TOP500 超級計算機",-1)])]),_:1}),e[4]||(e[4]=i(" 也依賴於 Linux。如果你擁有一台 Android 智能手機，那麼你的操作系統就是由 Linux 內核構建的。",-1))]),e[21]||(e[21]=p(`<p>換句話説，Linux 無處不在。</p><p>但是使用基於 Linux 的技術和使用 Linux 本身是有區別的。如果你對 Linux 感興趣，但是一直在使用 PC 或者 Mac 桌面，你可能想知道你需要知道什麼才能使用 Linux 命令列接口（CLI），那麼你來到了正確的地方。</p><p>下面是你需要知道的基本的 Linux 命令。每一個都很簡單，也很容易記住。換句話説，你不必成為比爾蓋茨就能理解它們。</p><h3 id="_1、-ls" tabindex="-1">1、 ls <a class="header-anchor" href="#_1、-ls" aria-label="Permalink to “1、 ls”">​</a></h3><p>你可能會想：“這是（is）什麼東西？”不，那不是一個印刷錯誤 —— 我真的打算輸入一個小寫的 l。<code>ls</code>，或者説 “list”， 是你需要知道的使用 Linux CLI 的第一個命令。這個 list 命令在 Linux 終端中運行，以顯示在存放在相應文件系統下的所有主要目錄。例如，這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls /applications</span></span></code></pre></div><p>顯示存儲在 <code>applications</code> 文件夾下的每個文件夾，你將使用它來查看文件、文件夾和目錄。</p><p>顯示所有隱藏的文件都可以使用命令 <code>ls -a</code>。</p><h3 id="_2、-cd" tabindex="-1">2、 cd <a class="header-anchor" href="#_2、-cd" aria-label="Permalink to “2、 cd”">​</a></h3><p>這個命令是你用來跳轉（或“更改”）到一個目錄的。它指導你如何從一個文件夾導航到另一個文件夾。假設你位於 <code>Downloads</code> 文件夾中，但你想到名為 <code>Gym Playlist</code> 的文件夾中，簡單地輸入 <code>cd Gym Playlist</code> 將不起作用，因為 shell 不會識別它，並會報告你正在查找的文件夾不存在（LCTT 譯註：這是因為目錄名中有空格）。要跳轉到那個文件夾，你需要包含一個反斜槓。改命令如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd Gym\\ Playlist</span></span></code></pre></div><p>要從當前文件夾返回到上一個文件夾，你可以在該文件夾輸入 <code>cd ..</code>。把這兩個點想像成一個後退按鈕。</p><h3 id="_3、-mv" tabindex="-1">3、 mv <a class="header-anchor" href="#_3、-mv" aria-label="Permalink to “3、 mv”">​</a></h3><p>該命令將文件從一個文件夾轉移到另一個文件夾；<code>mv</code> 代表“移動”。你可以使用這個簡單的命令，就像你把一個文件拖到 PC 上的一個文件夾一樣。</p><p>例如，如果我想創建一個名為 <code>testfile</code> 的文件來演示所有基本的 Linux 命令，並且我想將它移動到我的 <code>Documents</code> 文件夾中，我將輸入這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mv /home/sam/testfile /home/sam/Documents/</span></span></code></pre></div><p>命令的第一部分（<code>mv</code>）説我想移動一個文件，第二部分（<code>home/sam/testfile</code>）表示我想移動的文件，第三部分（<code>/home/sam/Documents/</code>）表示我希望傳輸文件的位置。</p><h3 id="_4、-快捷鍵" tabindex="-1">4、 快捷鍵 <a class="header-anchor" href="#_4、-快捷鍵" aria-label="Permalink to “4、 快捷鍵”">​</a></h3><p>好吧，這不止一個命令，但我忍不住把它們都包括進來。為什麼？因為它們能節省時間並避免經歷頭痛。</p><ul><li><code>CTRL+K</code> 從光標處剪切文本直至本行結束</li><li><code>CTRL+Y</code> 粘貼文本</li><li><code>CTRL+E</code> 將光標移到本行的末尾</li><li><code>CTRL+A</code> 將光標移動到本行的開頭</li><li><code>ALT+F</code> 跳轉到下一個空格處</li><li><code>ALT+B</code> 回到前一個空格處</li><li><code>ALT+Backspace</code> 刪除前一個詞</li><li><code>CTRL+W</code> 剪切光標前一個詞</li><li><code>Shift+Insert</code> 將文本粘貼到終端中</li><li><code>Ctrl+D</code> 註銷</li></ul><p>這些命令在許多方面都能派上用場。例如，假設你在命令列文本中拼錯了一個單詞：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get intall programname</span></span></code></pre></div><p>你可能注意到 <code>install</code> 拼寫錯了，因此該命令無法工作。但是快捷鍵可以讓你很容易回去修復它。如果我的光標在這一行的末尾，我可以按下兩次 <code>ALT+B</code> 來將光標移動到下面用 <code>^</code> 符號標記的地方：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get^intall programname</span></span></code></pre></div><p>現在，我們可以快速地添加字母 <code>s</code> 來修復 <code>install</code>，十分簡單！</p><h3 id="_5、-mkdir" tabindex="-1">5、 mkdir <a class="header-anchor" href="#_5、-mkdir" aria-label="Permalink to “5、 mkdir”">​</a></h3><p>這是你用來在 Linux 環境下創建目錄或文件夾的命令。例如，如果你像我一樣喜歡 DIY，你可以輸入 <code>mkdir DIY</code> 為你的 DIY 項目創建一個目錄。</p><h3 id="_6、-at" tabindex="-1">6、 at <a class="header-anchor" href="#_6、-at" aria-label="Permalink to “6、 at”">​</a></h3><p>如果你想在特定時間運行 Linux 命令，你可以將 <code>at</code> 添加到語句中。語法是 <code>at</code> 後面跟着你希望命令運行的日期和時間，然後命令提示符變為 <code>at&gt;</code>，這樣你就可以輸入在上面指定的時間運行的命令。</p><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>at 4:08 PM Sat</span></span>
<span class="line"><span>at&gt; cowsay &#39;hello&#39;</span></span>
<span class="line"><span>at&gt; CTRL+D</span></span></code></pre></div><p>這將會在週六下午 4:08 運行 <code>cowsay</code> 程序。</p><h3 id="_7、-rmdir" tabindex="-1">7、 rmdir <a class="header-anchor" href="#_7、-rmdir" aria-label="Permalink to “7、 rmdir”">​</a></h3><p>這個命令允許你通過 Linux CLI 刪除一個目錄。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rmdir testdirectory</span></span></code></pre></div><p>請記住，這個命令不會刪除裏面有文件的目錄。這隻在刪除空目錄時才起作用。</p><h3 id="_8、-rm" tabindex="-1">8、 rm <a class="header-anchor" href="#_8、-rm" aria-label="Permalink to “8、 rm”">​</a></h3><p>如果你想刪除文件，<code>rm</code> 命令就是你想要的。它可以刪除文件和目錄。要刪除一個文件，鍵入 <code>rm testfile</code>，或者刪除一個目錄和裏面的文件，鍵入 <code>rm -r</code>。</p><h3 id="_9、-touch" tabindex="-1">9、 touch <a class="header-anchor" href="#_9、-touch" aria-label="Permalink to “9、 touch”">​</a></h3><p><code>touch</code> 命令，也就是所謂的 “make file 的命令”，允許你使用 Linux CLI 創建新的、空的文件。很像 <code>mkdir</code> 創建目錄，<code>touch</code> 會創建文件。例如，<code>touch testfile</code> 將會創建一個名為 testfile 的空文件。</p><h3 id="_10、-locate" tabindex="-1">10、 locate <a class="header-anchor" href="#_10、-locate" aria-label="Permalink to “10、 locate”">​</a></h3><p>這個命令是你在 Linux 系統中用來查找文件的命令。就像在 Windows 中搜索一樣，如果你忘了存儲文件的位置或它的名字，這是非常有用的。</p><p>例如，如果你有一個關於區塊鏈用例的文檔，但是你忘了標題，你可以輸入 <code>locate -blockchain</code> 或者通過用星號分隔單詞來查找 &quot;blockchain use cases&quot;，或者星號（<code>*</code>）。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>locate -i*blockchain*use*cases*</span></span></code></pre></div><p>還有很多其他有用的 Linux CLI 命令，比如 <code>pkill</code> 命令，如果你開始關機但是你意識到你並不想這麼做，那麼這條命令很棒。但是這裏描述的 10 個簡單而有用的命令是你開始使用 Linux 命令列所需的基本知識。</p><hr>`,46)),a("p",null,[e[6]||(e[6]=i("via: ",-1)),t(s,{href:"https://opensource.com/article/18/4/10-commands-new-linux-users"},{default:l(()=>[...e[5]||(e[5]=[i("https://opensource.com/article/18/4/10-commands-new-linux-users",-1)])]),_:1})]),a("p",null,[e[10]||(e[10]=i("作者：",-1)),t(s,{href:"https://opensource.com/users/sambocetta"},{default:l(()=>[...e[7]||(e[7]=[i("Sam Bocetta",-1)])]),_:1}),e[11]||(e[11]=i(" 譯者：",-1)),t(s,{href:"https://github.com/MjSeven"},{default:l(()=>[...e[8]||(e[8]=[i("MjSeven",-1)])]),_:1}),e[12]||(e[12]=i(" 校對：",-1)),t(s,{href:"https://github.com/wxy"},{default:l(()=>[...e[9]||(e[9]=[i("wxy",-1)])]),_:1})]),a("p",null,[e[15]||(e[15]=i("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[13]||(e[13]=[i("LCTT",-1)])]),_:1}),e[16]||(e[16]=i(" 原創編譯，",-1)),t(s,{href:"https://linux.cn/"},{default:l(()=>[...e[14]||(e[14]=[i("Linux中國",-1)])]),_:1}),e[17]||(e[17]=i(" 榮譽推出",-1))])])}const C=o(c,[["render",h]]);export{L as __pageData,C as default};
